"""Bulgular, hipotez değerlendirmesi, jüri soruları ve yapılacaklar — sayılar sonuç dosyalarından çekilir (elle yazılmaz)."""
import json
from scipy.stats import t as tdist, norm
from tezlib import ROOT

CK = ROOT / "analiz" / "cikti"
